const rawText = $json.text;

if (!rawText) {
  throw new Error("AI response does not contain a 'text' field.");
}

let parsed;

try {
  parsed = JSON.parse(rawText);
} catch (error) {
  throw new Error(
    `AI returned invalid JSON: ${error.message}\n\nRaw response:\n${rawText}`
  );
}

return [
  {
    json: parsed
  }
];

const invoice = $json;

const anomalies = [];

// --------------------------------------------------
// 1. Required field validation
// --------------------------------------------------

if (!invoice.vendor || String(invoice.vendor).trim() === '') {
  anomalies.push('Missing vendor');
}

if (!invoice.invoice_number || String(invoice.invoice_number).trim() === '') {
  anomalies.push('Missing invoice number');
}

if (!invoice.invoice_date || String(invoice.invoice_date).trim() === '') {
  anomalies.push('Missing invoice date');
}

if (invoice.total === null || invoice.total === undefined) {
  anomalies.push('Missing total');
}

if (invoice.subtotal === null || invoice.subtotal === undefined) {
  anomalies.push('Missing subtotal');
}

if (invoice.currency === null || invoice.currency === undefined) {
  anomalies.push('Missing currency');
}

// --------------------------------------------------
// 2. Validate line items
// --------------------------------------------------

let calculatedSubtotal = 0;

if (!Array.isArray(invoice.line_items)) {
  anomalies.push('Line items are missing or invalid');
} else {

  invoice.line_items.forEach((item, index) => {

    const quantity = Number(item.quantity);
    const unitPrice = Number(item.unit_price);
    const amount = Number(item.amount);

    if (!item.description) {
      anomalies.push(`Line item ${index + 1}: missing description`);
    }

    if (!Number.isFinite(quantity)) {
      anomalies.push(`Line item ${index + 1}: invalid quantity`);
    }

    if (!Number.isFinite(unitPrice)) {
      anomalies.push(`Line item ${index + 1}: invalid unit price`);
    }

    if (!Number.isFinite(amount)) {
      anomalies.push(`Line item ${index + 1}: invalid amount`);
    }

    if (
      Number.isFinite(quantity) &&
      Number.isFinite(unitPrice) &&
      Number.isFinite(amount)
    ) {

      const expectedAmount = quantity * unitPrice;

      if (Math.abs(expectedAmount - amount) > 0.01) {
        anomalies.push(
          `Line item ${index + 1}: amount mismatch`
        );
      }

      calculatedSubtotal += amount;
    }
  });
}

// --------------------------------------------------
// 3. Validate subtotal against line items
// --------------------------------------------------

if (
  Number.isFinite(calculatedSubtotal) &&
  invoice.subtotal !== null &&
  invoice.subtotal !== undefined
) {

  const subtotal = Number(invoice.subtotal);

  if (Math.abs(calculatedSubtotal - subtotal) > 0.01) {
    anomalies.push(
      `Subtotal mismatch: line items = ${calculatedSubtotal}, invoice subtotal = ${subtotal}`
    );
  }
}

// --------------------------------------------------
// 4. Validate subtotal + tax = total
// --------------------------------------------------

if (
  invoice.subtotal !== null &&
  invoice.subtotal !== undefined &&
  invoice.tax !== null &&
  invoice.tax !== undefined &&
  invoice.total !== null &&
  invoice.total !== undefined
) {

  const subtotal = Number(invoice.subtotal);
  const tax = Number(invoice.tax);
  const total = Number(invoice.total);

  const calculatedTotal = subtotal + tax;

  if (Math.abs(calculatedTotal - total) > 0.01) {
    anomalies.push(
      `Total mismatch: subtotal + tax = ${calculatedTotal}, invoice total = ${total}`
    );
  }
}

// --------------------------------------------------
// 5. Validate confidence
// --------------------------------------------------

if (
  invoice.confidence === null ||
  invoice.confidence === undefined
) {

  anomalies.push('Missing AI confidence');

} else {

  const confidence = Number(invoice.confidence);

  if (!Number.isFinite(confidence)) {
    anomalies.push('Invalid AI confidence');

  } else if (confidence < 0.75) {
    anomalies.push(
      `Low AI confidence: ${confidence}`
    );
  }
}

// --------------------------------------------------
// 6. Validate expense category
// --------------------------------------------------

const validCategories = [
  'Office Supplies',
  'Software',
  'Hardware',
  'Travel',
  'Meals',
  'Utilities',
  'Marketing',
  'Professional Services',
  'Rent',
  'Shipping',
  'Other'
];

if (
  invoice.expense_category &&
  !validCategories.includes(invoice.expense_category)
) {
  anomalies.push(
    `Invalid expense category: ${invoice.expense_category}`
  );
}

// --------------------------------------------------
// 7. Final status
// --------------------------------------------------

const hasAnomalies = anomalies.length > 0;

return [
  {
    json: {
      ...invoice,

      validation: {
        has_anomalies: hasAnomalies,
        anomaly_count: anomalies.length,
        anomalies: anomalies,
        calculated_subtotal: Number(calculatedSubtotal.toFixed(2)),
        calculated_total:
          invoice.subtotal != null && invoice.tax != null
            ? Number(
                (Number(invoice.subtotal) + Number(invoice.tax)).toFixed(2)
              )
            : null
      },

      status: hasAnomalies
        ? 'REVIEW_REQUIRED'
        : 'VALIDATED'
    }
  }
];

return [
  {
    json: {
      ...$json,
      branch: 'CLEAN',
      duplicate_check_data: {
        vendor: $json.vendor,
        invoice_number: $json.invoice_number
      }
    }
  }
];

return [
  {
    json: {
      ...$json,

      original_invoice: {
        vendor: $json.vendor,
        invoice_number: $json.invoice_number,
        invoice_date: $json.invoice_date,
        tax_id: $json.tax_id,
        currency: $json.currency,
        line_items: $json.line_items,
        subtotal: $json.subtotal,
        tax: $json.tax,
        total: $json.total,
        expense_category: $json.expense_category,
        confidence: $json.confidence,
        validation: $json.validation,
        status: $json.status
      }
    }
  }
];

const original = $('Prepare Duplicate Check').first().json;

return [
  {
    json: {
      ...original,

      status: "READY_FOR_APPROVAL",
      duplicate_detected: false,
      review_reason: null
    }
  }
];

return [
  {
    json: {
      ...$json,
      approval_required: true,
      approval_status: "PENDING",
      approval_requested_at: new Date().toISOString(),
      approval_message:
        `Invoice ${$json.invoice_number} from ${$json.vendor} ` +
        `for ${$json.currency} ${$json.total} requires approval.`
    }
  }
];

