const ledgerResults = $('Check Duplicate Invoice1').all();
const pendingResults = $('Check Pending Invoice Duplicate').all();

const ledgerDuplicate = ledgerResults.some(item => {
  return item.json && Object.keys(item.json).length > 0;
});

const pendingDuplicate = pendingResults.some(item => {
  return (
    item.json &&
    Object.keys(item.json).length > 0 &&
    item.json.approval_status === 'PENDING'
  );
});

const isDuplicate = ledgerDuplicate || pendingDuplicate;

const original = $('Prepare Duplicate Check').first().json;

return [
  {
    json: {
      ...original,
      is_duplicate: isDuplicate,
      duplicate_source: ledgerDuplicate
        ? 'INVOICE_LEDGER'
        : pendingDuplicate
          ? 'PENDING_INVOICES'
          : null
    }
  }
];
